SELECT id, customer_id, created_at, ship_to, attributes, TRANSFORM(FILTER(items, x -> x.promo IS NOT NULL), x -> STRUCT(x.product_id AS pid, ROUND(x.price * 0.9, 2) AS discounted_price)) AS promo_lines, COALESCE(attributes['gift'], 'none') AS gift_or_default, attributes['utm_source'] AS utm_source, ship_to.city AS ship_city, ARRAY_CONTAINS(MAP_KEYS(attributes), 'weight_kg') AS has_weight_kg FROM carts
